<?php require_once __DIR__.'/includes/bootstrap.php';require_manager();$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$pdo=db();$s=$pdo->prepare("SELECT COUNT(*) orders_count,COALESCE(SUM(total),0) revenue FROM sales WHERE status='completed' AND DATE(created_at) BETWEEN ? AND ?");$s->execute([$from,$to]);$sum=$s->fetch();$s=$pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE DATE(expense_date) BETWEEN ? AND ?");$s->execute([$from,$to]);$expenses=$s->fetchColumn();$s=$pdo->prepare("SELECT DATE(created_at) day,COUNT(*) orders_count,SUM(total) revenue FROM sales WHERE status='completed' AND DATE(created_at) BETWEEN ? AND ? GROUP BY DATE(created_at) ORDER BY day DESC");$s->execute([$from,$to]);$days=$s->fetchAll();$pageTitle='Reports';require 'includes/header.php';?>
<div class="panel"><div class="panel-head"><div><h2>Sales report</h2><p class="muted">Choose a period to review performance.</p></div><form class="date-filter"><input type="date" name="from" value="<?=e($from)?>"><input type="date" name="to" value="<?=e($to)?>"><button class="btn primary">Apply</button></form></div><div class="stats-grid compact"><div class="stat-card"><small>Sales revenue</small><strong><?=money($sum['revenue'])?></strong></div><div class="stat-card"><small>Transactions</small><strong><?=number_format($sum['orders_count'])?></strong></div><div class="stat-card"><small>Recorded expenses</small><strong><?=money($expenses)?></strong></div><div class="stat-card"><small>Revenue less expenses</small><strong><?=money($sum['revenue']-$expenses)?></strong><em>Not net profit; stock costs and other costs are not included.</em></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Transactions</th><th>Revenue</th></tr></thead><tbody><?php foreach($days as $d):?><tr><td><?=date('D, d M Y',strtotime($d['day']))?></td><td><?=$d['orders_count']?></td><td><b><?=money($d['revenue'])?></b></td></tr><?php endforeach;?><?php if(!$days):?><tr><td colspan="3" class="empty">No sales in this period.</td></tr><?php endif;?></tbody></table></div></div><?php require 'includes/footer.php';?>
